"""Evidence-first bilingual materials, only after actual six-run statistics."""
import argparse
import pandas as pd
from common import config,setup,jread,jout,ARMS,now
from v5_safety import V3,enable_history_reference
def main(path):
    c=config(path);root=setup(c['project_private']);enable_history_reference(root);assert jread(root/'releases/FINAL_V5_STATUS.json')['RUNS_AND_METRICS_COMPLETE']
    ens=pd.read_csv(root/'tables/V5_THREE_SEED_ENSEMBLE.csv');seeds=pd.read_csv(root/'tables/V5_SEED_LEVEL_METRICS.csv');boot=pd.read_csv(root/'tables/V5_PAIR_BOOTSTRAP.csv')
    real,op=[ens[ens.arm.eq(a)].iloc[0] for a in ARMS];auc,ap=[boot[boot.metric.eq(m)].iloc[0] for m in ['ROC_AUC','AP']]
    def write(name,title,pairs):
        text='# '+title+'\n\n'+'\n\n'.join(en+'\n\n'+zh for en,zh in pairs)+'\n'
        (root/'writing'/name).write_text(text,encoding='utf-8')
    write('LTSA_V5_METHODS_CN_EN.md','V5 Methods / 方法',[
        ('The two V5 arms used the same 860 training patients (617 HT-negative and 243 HT-positive) and 189 internal-validation patients (131 negative and 58 positive), with all 4,585/991 pre-target REAL examinations and 18,413/3,861 native views. The 686 previously frozen Original Progression nodes (4,116 images; historical B14 CPFM ON) were retained without reselection or new generation. Validation used REAL history only; Official Test content was not accessed.',
         'V5两臂使用相同860名训练患者（617阴性、243阳性）及189名内部验证患者（131阴性、58阳性），完整保留4,585/991次目标年度前真实检查和18,413/3,861张原生视图。既有686个Original Progression节点（4,116图，历史B14 CPFM ON）未重选或重生成；验证仅使用真实历史，未访问Official Test内容。'),
        ('Before reading pixels, each frozen query was attached to the first strictly later REAL examination within the historical window. A shared trainable offline-ImageNet ResNet18 encoded every REAL view and six images per node. REAL views were averaged per Exam; synthetic views were averaged per node and then equally across nodes attached to the same Exam. No synthetic temporal token was added.',
         '读取像素前，每个冻结query被附着到历史窗口内第一个严格晚于其日期的真实检查。共享、可训练、离线ImageNet初始化的ResNet18编码全部真实视图及每节点六图；真实视图检查内均值，合成图先节点内均值再对同Exam节点等权均值，不增加合成时间token。'),
        ('For attached Exams, two separate LayerNorm512 modules formed h_r and h_s. A scalar sigmoid gate from concatenated 1,024-D features modulated a 512→512 projection of h_s−h_r, with fixed residual scale 0.1. Unattached Exams bypassed all fusion operations exactly. Both arms contained 13,020,738 trainable parameters; new-module initialization preserved global Python, NumPy and Torch CPU/CUDA RNG. Standard train BatchNorm was retained, so additional synthetic images could alter its running statistics.',
         '有节点的Exam通过两个独立LayerNorm512形成h_r/h_s；拼接1024维输入的标量sigmoid门控调制h_s−h_r的512→512投影，残差系数固定0.1。无节点Exam严格旁路全部融合操作。两臂均有13,020,738可训练参数，新增模块初始化保持Python、NumPy、Torch CPU/CUDA随机状态；训练BN保持标准行为，新增合成图可能改变其运行统计。'),
        ('The original month sinusoidal positional encoding, one 4-head causal Transformer layer (512-D FFN, ReLU, dropout 0.25) and last-REAL binary head were retained. Each arm was independently trained at seeds 42, 3407 and 2026 using FP32 AdamW (learning rate and weight decay 10⁻⁴), 5-epoch warmup and cosine decay to epoch60, microbatch4/accumulation2, and complete differentiable view chunks16. Early stopping used max60/min15/patience12; best selection followed ROC-AUC, AP, lower loss and earlier epoch. No V3/V4 or previous-arm checkpoint initialized a run.',
         '保留原始月sinusoidal位置编码、单层四头因果Transformer（FFN512、ReLU、dropout0.25）及最后真实token二分类头。每臂分别以42、3407、2026独立训练，采用FP32 AdamW（学习率和weight decay均10⁻⁴）、5轮warmup后cosine至60轮、microbatch4/累积2、完整可微view chunk16。早停max60/min15/patience12，最佳顺序为AUC、AP、较低loss、较早epoch；未用V3/V4或前一臂权重初始化。'),
        ('Cached RGB224 pixels were ImageNet-normalized without new stochastic image augmentation. Training minimized unweighted binary cross-entropy with logits once per patient. Microbatch 4 with two accumulation steps produced an effective batch of 8; the final short accumulation group was normalized by its actual patient count. FP32, TF32-off, deterministic algorithms and math-only scaled-dot-product attention followed the frozen V3 numerical contract.',
         '已有RGB224缓存按ImageNet规范归一化，不增加随机影像增强。每患者一次无类别权重的BCEWithLogitsLoss监督。microbatch 4、累积2步对应有效batch 8；末尾不足8人的累积组按实际患者数归一化。FP32、关闭TF32、确定性算法及仅math SDPA均沿用冻结V3数值合同。'),
        ('Every best checkpoint was independently strictly reloaded within a 10⁻⁶ probability tolerance on the same ordered 189 patients. Ensembles averaged three positive-class probability vectors. AP denotes average_precision_score, not trapezoidal PR area. Youden-J internal-Val thresholds and fixed0.5 sensitivity analyses were reported. Patient-paired bootstrap used 2,000 draws at seed20261013 with single-class skips recorded.',
         '每个best checkpoint均独立strict重载，同189人顺序的概率容差10⁻⁶；集成为三种子正类概率均值。AP为average_precision_score而非梯形PR面积。报告内部Val Youden-J阈值及固定0.5敏感性分析；患者配对bootstrap为固定seed20261013的2,000次，并记录单类跳过数。')])
    pairs=[]
    for label,row in [('REAL-only',real),('Original Progression fusion',op)]:
        values=f"ROC-AUC {row.ROC_AUC:.6f}, AP {row.AP:.6f}, accuracy {row.Accuracy:.6f}, precision {row.Precision:.6f}, sensitivity {row.Sensitivity:.6f}, specificity {row.Specificity:.6f}, and F1 {row.F1:.6f}"
        matrix=f"TN/FP/FN/TP {int(row.TN)}/{int(row.FP)}/{int(row.FN)}/{int(row.TP)}"
        zh_values=f'ROC-AUC {row.ROC_AUC:.6f}、AP {row.AP:.6f}、准确率 {row.Accuracy:.6f}、精确率 {row.Precision:.6f}、敏感度 {row.Sensitivity:.6f}、特异度 {row.Specificity:.6f}、F1 {row.F1:.6f}'
        pairs.append((f'The {label} ensemble achieved {values} at its internal-Val Youden threshold {row.threshold:.6f} ({matrix}).',f'{label}集成实测{zh_values}，内部Val Youden阈值为{row.threshold:.6f}（{matrix}）。'))
    for row in seeds.itertuples(index=False):pairs.append((f'{row.arm}, seed {row.seed}: best epoch {row.best_epoch}, {row.actual_epochs} completed epochs, AUC {row.ROC_AUC:.6f}, AP {row.AP:.6f}, F1 {row.F1:.6f}; independent strict reload passed.',f'{row.arm}，seed {row.seed}：最佳{row.best_epoch}轮，实际{row.actual_epochs}轮，AUC {row.ROC_AUC:.6f}、AP {row.AP:.6f}、F1 {row.F1:.6f}；独立strict重载通过。'))
    pairs.append((f'OP−REAL differences were {auc.delta_OP_minus_REAL:.6f} for ROC-AUC (95%CI {auc.ci_low:.6f} to {auc.ci_high:.6f}) and {ap.delta_OP_minus_REAL:.6f} for AP (95%CI {ap.ci_low:.6f} to {ap.ci_high:.6f}); {int(auc.bootstrap_valid)}/2,000 paired draws were valid and {int(auc.bootstrap_skipped_one_class)} single-class draws were skipped.',f'OP−REAL ROC-AUC差为{auc.delta_OP_minus_REAL:.6f}（95%CI {auc.ci_low:.6f}至{auc.ci_high:.6f}），AP差为{ap.delta_OP_minus_REAL:.6f}（95%CI {ap.ci_low:.6f}至{ap.ci_high:.6f}）；2,000次配对重采样中{int(auc.bootstrap_valid)}次有效，跳过{int(auc.bootstrap_skipped_one_class)}次单类样本。'))
    pairs.append(('The frozen V3/V4 ensembles were REAL AUC0.859042/AP0.810942 and virtual-query OP AUC0.790208/AP0.698502. Their OP−REAL differences were −0.068834/−0.112441. Comparison with V5 is descriptive because the fusion gate and encoding path also differ; private REAL probability diagnostics are summarized separately.', '冻结V3/V4集成为REAL AUC0.859042/AP0.810942、虚拟query OP AUC0.790208/AP0.698502，差值−0.068834/−0.112441。与V5仅作描述比较，因为gate和编码路径也变化；真实对照的私有概率一致性另表聚合报告。'))
    parity=pd.read_csv(root/'tables/V5_REAL_NUMERICAL_PARITY_DIAGNOSTIC.csv')
    max_difference=float(parity.max_abs_probability_difference.max())
    pairs.append((f'The V5 REAL-only probabilities matched the frozen V3 and V4 REAL-only probabilities across all three seeds and the ensemble: the maximum absolute difference across the eight aligned comparisons was {max_difference:.8g}. This was a numerical implementation diagnostic, not a performance gate or a reason to retune the fusion arm.',f'V5 REAL-only与冻结V3/V4的三个seed及集成逐人概率保持一致；八项对齐比较的最大绝对差为{max_difference:.8g}。这只是数值实现诊断，不是性能Gate，也不据此重新调节融合臂。'))
    write('LTSA_V5_RESULTS_CN_EN.md','V5 Results / 结果',pairs)
    write('LTSA_V5_DISCUSSION_LIMITATIONS_CN_EN.md','V5 Discussion and limitations / 讨论与局限',[
        (f'The observed V5 OP−REAL effects were AUC{auc.delta_OP_minus_REAL:.6f} and AP{ap.delta_OP_minus_REAL:.6f}. Both patient-bootstrap confidence intervals included zero: the AUC point estimate increased while AP slightly decreased, without clear evidence of a stable advantage on this internal-validation set. These measurements evaluated the single pre-registered fusion strategy and did not trigger further tuning or selective retraining. Neither direction establishes a universal benefit or failure of synthetic imaging.',f'V5实测OP−REAL效应为AUC{auc.delta_OP_minus_REAL:.6f}、AP{ap.delta_OP_minus_REAL:.6f}。两个患者bootstrap置信区间均包含0：AUC点估计提高而AP略降，尚无清晰证据支持本内部验证集上的稳定增益。这里只评价唯一预设融合方案，不据此调参或择优复训；无论正负都不能建立合成图像普遍有效或无效的结论。'),
        ('The method retains REAL token counts and observed month indices, but it also introduces a learned residual gate and projection, different image encoding order, and potential BatchNorm changes. Cross-protocol V3/V4 versus V5 differences therefore cannot isolate token count as the unique causal explanation. Attaching query content to a later historical REAL Exam is retrospective within-window augmentation, not prediction at query time using an actually future REAL examination.', '该方法保持真实token数量和观测月份，但也引入学习残差gate/projection、不同编码顺序及可能的BN变化。跨协议差异不能唯一归因于token数。把query信息附着后续历史真实检查是窗口内后验增强，不是在query时刻利用实际未来真实检查预测。'),
        ('All evaluation concerns the same 189 internal-validation patients. Prior V3/V4 outcomes informed the choice of V5, and validation also selected checkpoints, stopping and thresholds. Patient bootstrap does not capture all adaptive design and selection uncertainty. No independent clinical generalization, Official Test performance, or superiority over all generators is claimed.', '评价仅涉及相同189名内部验证患者；既有V3/V4结果影响V5设计，Val也参与checkpoint、早停和阈值选择。患者bootstrap不能覆盖全部适应性设计/选择不确定性，不能声称独立临床泛化、Official Test表现或优于所有生成器。')])
    captions=[('Fig.1 | V5 matched internal-validation ROC and precision–recall. REAL-only blue solid lines and OP fusion amber dashed lines represent three-seed probability ensembles on n=189 patients (58 positive). AP is average precision, not trapezoidal PR area. Dashed gray references show chance ROC and positive prevalence for PR. Source data are provided as aggregate curve coordinates; no patient-level data are released.', '图1 | V5匹配内部验证ROC与PR曲线。蓝色实线REAL及琥珀色虚线OP代表189人（58阳性）的三种子概率集成；AP为average precision而非梯形PR面积。灰色虚线表示随机ROC及PR阳性率基线。仅提供聚合曲线坐标作为源数据，不发布逐人数据。'),
       ('Fig.2 | Descriptive cross-protocol ensemble comparison. Six rows compare V3/V4 virtual-query augmentation with V5 Exam fusion and their REAL controls. Bars are measured ensemble AUC/AP, not independent patient replicates or a causal token-count contrast.', '图2 | 跨协议集成描述性比较。六行比较V3/V4虚拟query增强与V5检查级融合及其REAL对照；柱为集成AUC/AP，不是独立患者重复，也不是token数量因果对照。'),
       ('Fig.3 | All V5 seeds and ensembles. Seeds42/3407/2026 are independent training initializations on the same split; no seed is omitted. Ensemble is arithmetic mean of probabilities, not mean of the plotted metrics.', '图3 | V5全部seed与集成。42/3407/2026是相同拆分上独立训练初始化，不省略任何seed；集成是概率算术均值，不是图中指标的均值。'),
       ('Fig.4 | Internal architecture of next-real Exam fusion. Anonymous REAL timeline and frozen query binding precede shared image encoding, node-equal averaging, separate LayerNorms, scalar sigmoid gate, 512-D difference projection and fixed0.1 residual. Empty synthetic masks follow strict identity. Original temporal masks and last-REAL readout are retained; no medical images or patient dates are depicted.', '图4 | next-real检查融合内部结构。匿名时间线/query映射之后为共享编码、节点等权均值、独立LayerNorm、标量sigmoid gate、512维差值projection及固定0.1残差；无合成掩码走严格恒等支路，保留原时间掩码/最后REAL读出；无医学图像或患者日期。'),
       ('Tables | Seed-level and ensemble metrics, paired bootstrap and frozen input support. Threshold-related metrics use internal-Val Youden-J or explicitly labeled fixed0.5 thresholds. Confidence intervals use 2,000 patient-paired resamples, fixed seed20261013 and reported single-class skips; no multiplicity-adjusted universal inference is made.', '表 | 每seed/集成指标、配对bootstrap及冻结输入支持。阈值指标用内部Val Youden-J或明确标记的0.5；CI为固定seed20261013的2,000次患者配对重采样并报告单类跳过，不作多重校正后的普遍推断。')]
    write('LTSA_V5_TABLE_FIGURE_CAPTIONS_CN_EN.md','V5 captions / 图表注',captions)
    reference=pd.read_csv(V3/'tables/LTSA_VS_CLIMAT_WITHIN_PREDICTOR_REFERENCE_V3.csv');ref=reference[reference.predictor.eq('CLIMATv2_historical_runbook_reference')].iloc[0]
    write('LTSA_V5_INTEGRATION_WITH_CLIMAT_CN_EN.md','Descriptive integration / 描述性整合',[(f'The pre-existing CLIMATv2 fixedK6 historical reference reports REAL ensemble AUC{ref.REAL_ROC_AUC:.6f} and OP AUC{ref.OP_ROC_AUC:.6f} (difference{ref.delta_OP_minus_REAL:.6f}). These values were retrieved from the frozen historical reference table, not rerun here. CLIMAT used full9,270 historical synthetic images, whereas LTSA V3/V4/V5 use686 bounded nodes/4,116 images and complete native REAL Exams. Predictor, image organization and synthetic exposure are not input-equivalent.',f'既有CLIMATv2 fixedK6历史参考为REAL集成AUC{ref.REAL_ROC_AUC:.6f}、OP AUC{ref.OP_ROC_AUC:.6f}（差{ref.delta_OP_minus_REAL:.6f}）。值取自冻结历史参考表，本轮未重跑。CLIMAT使用完整9,270张历史合成图；LTSA V3/V4/V5使用686个bounded节点/4,116图及完整原生真实Exam。预测器、组织与合成曝光不等价。'),(f'V5 LTSA measured REAL AUC{real.ROC_AUC:.6f} and OP fusion AUC{op.ROC_AUC:.6f}. The opposite or similar direction across predictors remains a descriptive observation, not a paired cross-model superiority test or proof that any single module causes the discrepancy.',f'V5 LTSA实测REAL AUC{real.ROC_AUC:.6f}、OP融合AUC{op.ROC_AUC:.6f}。不同预测器方向一致或相反都仅是描述观察，不构成跨模型配对优越检验或某单模块导致差异的证据。')])
    jout(root/'writing/V5_WRITING_QA.json',dict(status='PASS_GENERATED_FROM_ACTUAL_AGGREGATES',bilingual_files=5,paragraph_order='English immediately followed by Chinese',clinical_certification=False,journal_submission_certification=False,needs_author_review=True,created_utc=now()))
    print(dict(bilingual_files=5,actual_results_used=True,author_review='PENDING'),flush=True)
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--config',required=True);main(p.parse_args().config)
